if(section[0]==='sobre-ciba'&&item&&item[0]==='mision-y-lema'){
 const mission='<section class="legal-section"><h2>Nuestra misión</h2><p>CIBA es una plataforma cubana de educación parental digital en los primeros mil días de las infancias. Su misión es acercar a las familias, los profesionales y la comunidad conocimientos confiables, comprensibles y útiles sobre el embarazo, el nacimiento y los primeros dos años de vida, una etapa decisiva para la salud, el desarrollo y el bienestar a lo largo de la vida.</p><p>Trabajamos para facilitar el acceso al conocimiento científico y a recursos educativos de calidad, promover prácticas de crianza respetuosas, fortalecer el acompañamiento familiar y contribuir a una cultura de cuidado basada en la evidencia, la responsabilidad y el respeto a los derechos de cada persona.</p><p>Desde una perspectiva cubana, abierta al conocimiento universal y atenta a las realidades de las familias, integramos cuatro dimensiones complementarias: Crianza, Internet, Bienestar y Acompañamiento.</p><p>Aspiramos a construir un espacio de educación, aprendizaje y colaboración en el que las familias encuentren orientación responsable, los profesionales puedan compartir conocimientos y la comunidad participe en la construcción de entornos más saludables y favorables para el comienzo de la vida.</p><p>Nuestra labor se guía por el rigor científico, la independencia editorial, la transparencia, la inclusión y el compromiso con las personas.</p></section>';
 const vision='<section class="legal-section"><h2>Nuestra visión</h2><p>Convertirnos progresivamente en un ecosistema digital de educación parental en los primeros mil días de las infancias, articulando contenidos, herramientas, recursos y espacios de aprendizaje y colaboración que acompañen a las familias y fortalezcan las capacidades de quienes participan en el cuidado y la educación durante esta etapa.</p></section>';
 app.innerHTML='<header class="plataforma-top"><div class="plataforma-top-inner"><a class="plataforma-logo" href="'+root+'index.html">CIBA</a><a class="plataforma-volver" href="'+url('sobre-ciba/')+'">← Sobre CIBA</a></div></header><section class="plataforma-hero"><div class="plataforma-wrap"><div class="plataforma-kicker">CIBA · Sobre el proyecto</div><h1>Misión y lema</h1><p>El propósito que orienta el trabajo de CIBA y el sentido de nuestra identidad.</p><span class="plataforma-estado"><i>✺</i> Identidad del proyecto</span></div></section><main class="plataforma-main">'+crumb+'<p class="plataforma-intro">Nuestra razón de ser es acercar conocimiento confiable y acompañamiento responsable durante los primeros 1000 días.</p>'+mission+vision+'<section class="legal-section"><h2>Nuestro lema</h2><p class="sobre-ciba-lema">Crecemos acompañándonos.</p><p>Una invitación a compartir conocimiento, fortalecer los vínculos y acompañar a las familias y a quienes trabajan por el bienestar durante el comienzo de la vida.</p></section><aside class="plataforma-nota"><span class="plataforma-nota-icon">✧</span><div><h2>Cuatro dimensiones, un propósito</h2><p>Crianza · Internet · Bienestar · Acompañamiento.</p></div></aside></main><footer class="plataforma-pie">CIBA · Crecemos acompañándonos · <a href="'+root+'index.html">Inicio</a></footer>';
 const link=document.createElement('link');link.rel='stylesheet';link.href=root+'assets/css/ciba-plataforma.css?v=20261110-16';document.head.appendChild(link);
 const global=document.createElement('script');global.type='module';global.src=root+'assets/js/ciba-global.js?v=20261110-12';document.body.appendChild(global);return;
}

